import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import session from 'express-session';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

app.use(session({
  secret: process.env.SESSION_SECRET || 'dev-fallback-key',
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, secure: false }
}));

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: check session auth
function requireAuth(req, res, next) {
  if (req.session && req.session.userId) return next();
  return res.status(401).json({ error: 'Unauthorized' });
}

// User profile update - supports partial updates
app.put('/api/users/:id/profile', requireAuth, async (req, res) => {
  const userId = req.params.id;
  const updates = req.body;

  // Verify user can only update their own profile
  if (req.session.userId !== parseInt(userId)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const allowedFields = ['display_name', 'bio', 'avatar_url', 'preferences'];
  const setClauses = [];
  const values = [];
  let paramIndex = 1;

  for (const [key, value] of Object.entries(updates)) {
    if (allowedFields.includes(key)) {
      setClauses.push(`${key} = $${paramIndex}`);
      values.push(value);
      paramIndex++;
    }
  }

  if (setClauses.length === 0) {
    return res.status(400).json({ error: 'No valid fields to update' });
  }

  values.push(userId);
  const query = `UPDATE user_profiles SET ${setClauses.join(', ')}, updated_at = NOW() WHERE user_id = $${paramIndex}`;

  try {
    await pool.query(query, values);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: 'Update failed' });
  }
});

// Admin endpoint: generate report with user-specified template
app.post('/api/admin/reports', requireAuth, async (req, res) => {
  const { template, filters } = req.body;

  // Check admin role from session
  if (!req.session.isAdmin) {
    return res.status(403).json({ error: 'Admin access required' });
  }

  // Template rendering with user data interpolation
  const rendered = template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
    return filters[key] !== undefined ? filters[key] : match;
  });

  try {
    const result = await pool.query(rendered);
    res.json({ data: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Report generation failed', detail: err.message });
  }
});

// Password reset - generates token and stores hash
app.post('/api/auth/reset-password', async (req, res) => {
  const { email } = req.body;
  const token = crypto.randomBytes(32).toString('hex');
  const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

  try {
    await pool.query(
      'UPDATE users SET reset_token_hash = $1, reset_expires = NOW() + interval \'1 hour\' WHERE email = $2',
      [tokenHash, email]
    );
    // In production, send email with token
    res.json({ message: 'If account exists, reset email sent' });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Health check exposing version info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: process.env.APP_VERSION, node: process.version });
});

app.listen(3000, () => console.log('Service running on :3000'));
